//! KISS-Classify `structure_key` **reference vectors** — the machine-readable,
//! codec-generated byte-match set consumers diff against (Classify §6.7, sk4).
//!
//! This module is the single in-tree source for the reference token set published
//! as `conformance/corpus/structure_key_vectors.json`. Every token in that file is
//! **emitted by the reference codec at generation time** — positives are
//! [`StructureKey::to_token`] on a constructed key, declines are [`from_token`] run
//! against a malformed input — so nothing is hand-transcribed into the artifact. A
//! consumer diffing its own independent derivation against the file is comparing
//! against the reference implementation's actual output, not a human copy of it.
//!
//! The artifact exists because three independent implementations hand-transcribing
//! the golden tokens out of `tests/structure_key_golden.rs` is three chances to
//! introduce a difference that is not a real divergence — or worse, one that
//! *cancels* a real one. Generating the set once, from the codec, removes that
//! last-mile transcription entirely (mirrors `dtype_manifest.json`, the §6.1 SSOT).
//!
//! Coverage is bound to the frozen golden test additively, NOT by refactoring it:
//! `tests/structure_key_vectors.rs` `include_str!`s the golden source, scans out its
//! `sk4|` token literals, and asserts this set is a superset of them — so a golden
//! cell can never be silently dropped from the artifact, and no second transcription
//! exists to drift against the first.

use crate::structure_key::*;

/// Schema identity of the emitted artifact (mirrors `kiss-dtype-manifest-v1`).
pub const VECTORS_SCHEMA: &str = "kiss-structure-key-vectors-v1";
/// The merged spec/codec commit these vectors are generated from — falsifiable
/// provenance (§6.7 Appendix A at sk4, #131 `SCHEMA_VERSION` 3→4). An artifact that
/// names its source tree is checkable against that tree; one that does not is a
/// claim about an unspecified state.
/// **KNOWN DEFECT - #218, fix scheduled with the coordinated artifact cut.**
/// This literal is maintained by hand, so nothing moves it when the generator's
/// inputs move: it survived the decline set going 10 -> 15 -> 17 and the vulkan v4
/// respell unchanged. The doc comment above calls it "falsifiable provenance", and
/// that is the claim being falsified here - a stamp proves BINDING, not CURRENCY. It
/// records which tree was bound and structurally cannot report that the tree has
/// since moved. The fix derives the value at generation time under a NEW field name
/// (the old one deprecated, never redefined in place); it changes published bytes,
/// so it ships with the coordinated cut. DO NOT COPY THIS PATTERN.
pub const SOURCE_COMMIT: &str = "19c3ad7";

/// The **vocabulary version** each embedded `<namespace>:` token was generated
/// against (§6.8-0004: a namespace's capability-set vocabulary is owned by that
/// namespace's maintainer, not by KISS).
///
/// Why this exists (#200). The artifact pinned `SOURCE_COMMIT` for the KISS spec
/// and recorded NOTHING about the maintainer-owned vocabularies its tokens are
/// spelled in. So a vocabulary could bump and the artifact go silently wrong with
/// no event marking the transition — and it did: `vulkan.md` reached version 4
/// (five fields, rule V-1) while this artifact still published a four-field token,
/// and the four-leg byte-match AGREED on it, because every consumer derived from
/// the same stale artifact rather than from the maintainer's document.
///
/// A match against a value you did not author is only as fresh as the thing you
/// did not author. This table is what makes that freshness checkable instead of
/// assumed; `reference_vectors_state_a_vocabulary_version_for_every_namespace`
/// ties each entry to the `**Vocabulary version:** N` header of the owning
/// document, so a bump fails CI at the moment it lands.
///
/// Each entry is `(namespace, vocabulary version, capability-set field arity)`.
///
/// The arity is the count of `.`-separated fields the owning document's grammar
/// requires — `cuda` C-1: one field (`sm<N>[<letter>]`); `vulkan` V-1, unchanged
/// from v4 through v5: exactly five, none omissible. Note the arity and the
/// vocabulary version move INDEPENDENTLY — v5 adds three `<arith>` names and no
/// field, so the version advances while the arity does not. It is pinned here so the GENERATOR can reject a
/// malformed token, and tied to the owning document by
/// `reference_vectors_match_the_namespace_documents`.
pub const NAMESPACE_VOCAB_VERSIONS: &[(&str, u32, usize)] = &[("cuda", 1, 1), ("vulkan", 5, 5)];

/// Validate an embedded `<namespace>:<capability-set>` target against the owning
/// document's grammar, at GENERATION time. Panics on any violation.
///
/// A version stamp catches a vocabulary BUMP; it does not catch a token that was
/// malformed the day it was written (#200). Both produce an artifact whose tokens no
/// consumer can derive independently — and the byte-match cannot tell them apart,
/// because every consumer copies the token from here. Arity is the part of the grammar
/// KISS can enforce without re-implementing a maintainer-owned vocabulary; the field
/// VOCABULARIES stay the maintainer's.
pub fn validate_target_token(target: &str) {
    let (ns, cap) = match target.split_once(':') {
        Some(p) => p,
        None => panic!("structure_key_vectors: target `{target}` has no `<namespace>:` prefix"),
    };
    let want = match NAMESPACE_VOCAB_VERSIONS.iter().find(|(n, _, _)| *n == ns) {
        Some((_, _, a)) => *a,
        None => panic!("structure_key_vectors: target `{target}` names namespace `{ns}:` with no recorded vocabulary; add it to NAMESPACE_VOCAB_VERSIONS (#200)"),
    };
    let got = cap.split('.').count();
    assert_eq!(
        got, want,
        "structure_key_vectors: target `{target}` has {got} capability-set field(s); spec/namespaces/{ns}.md requires exactly {want}. The artifact MUST NOT publish a token malformed under the vocabulary that owns it (#200)."
    );
}

/// The vocabulary version for `ns`, or a hard failure.
///
/// Deliberately a panic rather than an `Option`: this runs in the artifact
/// GENERATOR, and the obligation is that the artifact cannot be produced carrying a
/// namespace whose vocabulary version it is unable to state. A `None` that silently
/// emitted nothing would reproduce the exact defect — an artifact making a claim it
/// has no provenance for.
pub fn namespace_vocab_version(ns: &str) -> u32 {
    match NAMESPACE_VOCAB_VERSIONS.iter().find(|(n, _, _)| *n == ns) {
        Some((_, v, _)) => *v,
        None => panic!(
            "structure_key_vectors: a vector names namespace `{ns}:` but no vocabulary version is recorded for it. Add it to NAMESPACE_VOCAB_VERSIONS with the version from spec/namespaces/{ns}.md. The artifact MUST NOT publish a token whose vocabulary provenance it cannot state (#200)."
        ),
    }
}

// ---- construction helpers (same shapes the golden test constructs) -----------

fn op(contig: Contig, mask: u8, vec: VecWidth, div: DivBucket, flipped: bool) -> OperandSubKey {
    OperandSubKey { contig, bcast_mask: mask, vec, div, flipped }
}
fn co4() -> OperandSubKey { op(Contig::Contiguous, 0x00, VecWidth::V4, DivBucket::D16, false) }
fn co8() -> OperandSubKey { op(Contig::Contiguous, 0x00, VecWidth::V8, DivBucket::D16, false) }
fn br1() -> OperandSubKey { op(Contig::Broadcast, 0x01, VecWidth::V1, DivBucket::D16, false) }
fn co1_d8() -> OperandSubKey { op(Contig::Contiguous, 0x00, VecWidth::V1, DivBucket::D8, false) }
fn co1_da() -> OperandSubKey { op(Contig::Contiguous, 0x00, VecWidth::V1, DivBucket::Da, false) }

fn key(
    op_family: &str,
    dtype: &str,
    target: &str,
    work_class: WorkClass,
    rank: u32,
    operands: Vec<OperandSubKey>,
    reduce: Reduce,
    contraction: Option<Contraction>,
) -> StructureKey {
    StructureKey {
        op_family: op_family.to_string(),
        dtype: dtype.to_string(),
        target: target.to_string(),
        index_width: "ix32".to_string(),
        work_class,
        rank,
        operands,
        reduce,
        contraction,
        acc_mp: None,
    }
}

fn key_acc_mp(
    op_family: &str,
    dtype: &str,
    work_class: WorkClass,
    rank: u32,
    operands: Vec<OperandSubKey>,
    reduce: Reduce,
    acc_mp: Option<AccMp>,
) -> StructureKey {
    StructureKey {
        op_family: op_family.to_string(),
        dtype: dtype.to_string(),
        target: "cuda:sm89".to_string(),
        index_width: "ix32".to_string(),
        work_class,
        rank,
        operands,
        reduce,
        contraction: None,
        acc_mp,
    }
}

/// A dense `f32/f32/f32`, bit-stable, non-batched contraction group of the given
/// M/N/K size classes — the common precision-group shape.
fn ctr(m: SizeClass, n: SizeClass, k: SizeClass, batch: Option<SizeClass>, wdt: &str, acc: &str, out: &str, mp: MathPrecision) -> Contraction {
    Contraction {
        m, n, k, k_div: DivBucket::D16, batch,
        wdt: wdt.to_string(), acc: acc.to_string(), out: out.to_string(), mp,
    }
}

/// The namespace half of a `<namespace>:<capability-set>` target token (§6.8-0001) —
/// e.g. `cuda` for `cuda:sm90`, `vulkan` for `vulkan:sg64...`. The axis a consumer
/// scopes capability exclusions on: a namespace it does not implement is an exclusion,
/// not a divergence.
fn target_namespace(target: &str) -> &str {
    target.split(':').next().unwrap_or(target)
}

// ---- the reference vectors ---------------------------------------------------

/// One canonical positive vector: a constructed [`StructureKey`] and the exact token
/// the codec serializes it to. `token` is the Appendix-A golden literal, asserted
/// equal to `key.to_token()` in the vectors test (the spec-tie); the emitted artifact
/// carries `key.to_token()`, so the two are byte-identical by construction.
pub struct PositiveVector {
    pub name: &'static str,
    pub clause: &'static str,
    pub note: &'static str,
    pub key: StructureKey,
    pub token: &'static str,
}

