/// One KISS-CLASSIFY-6.8-0002 **match vector**: an ordered pair of `target_capability`
/// tokens and the verdict a byte-exact matcher MUST return for them.
///
/// The other §6.8 obligations are pinned by vectors whose CONTENT is checked, so a
/// re-generation reds when they drift. -0002 had no vector at all: a consumer asserting
/// it could only assert a PARAPHRASE of the clause, which rots silently when the clause
/// moves and is exactly as green as a live check while doing so.
///
/// `axis` names the forbidden matching logic the pair would fool. Byte-exactness is
/// **vocabulary-blind** by construction — a matcher must answer these without consulting
/// any namespace document — so the `ordering` and `subset` rows deliberately carry a
/// right-hand side that is NON-CANONICAL under `spec/namespaces/vulkan.md` V-3. That is
/// the point: a matcher that had to know it was non-canonical in order to decline it
/// would be consulting the vocabulary, which §6.8-0002 forbids.
pub struct MatchVector {
    pub name: &'static str,
    pub clause: &'static str,
    pub axis: &'static str,
    pub note: &'static str,
    pub left: &'static str,
    pub right: &'static str,
    pub expect_match: bool,
}

/// The §6.8-0002 match set: every forbidden logic the clause NAMES — ordering, subset,
/// prefix, feature-implication — plus the case axis §6.8-0005 ties to it, plus one
/// equal-pair CONTROL per namespace.
///
/// ⚠️ The controls are per-NAMESPACE, not one for the set. `target_axis_note` invites a
/// consumer to scope whole namespaces out as capability EXCLUSIONS; a single control
/// would live in one of them, and a consumer excluding that namespace would be left with
/// none. A matcher that answers `no-match` for EVERYTHING then passes every remaining row
/// — the vacuous-pass shape, reintroduced by the exclusion mechanism rather than by the
/// vector set.
///
/// `ordering` and `subset` are only expressible against a namespace whose capability-set
/// juxtaposes members (§6.8-0006). `cuda:` capability-sets are atomic, so the cuda rows
/// cannot reach those two axes at all; vulkan's `ops-` field is a fixed-width juxtaposed
/// set (`spec/namespaces/vulkan.md` V-5), which is what makes `ops-abr` vs `ops-bar` a
/// reordering and `ops-abr` vs `ops-ab` a proper subset rather than two unrelated strings.
pub fn target_match_vectors() -> Vec<MatchVector> {
    const VK: &str = "vulkan:sg64.ops-abr.arith-f16.cm-none.cv-none";
    vec![
        MatchVector {
            name: "equal_control_cuda",
            clause: "KISS-CLASSIFY-6.8-0002",
            axis: "control",
            note: "byte-equal targets MUST match -- without this row a matcher that answers no-match for everything passes every discriminating pair below",
            left: "cuda:sm89",
            right: "cuda:sm89",
            expect_match: true,
        },
        MatchVector {
            name: "prefix_right_shorter",
            clause: "KISS-CLASSIFY-6.8-0002",
            axis: "prefix",
            note: "right is a proper prefix of left: a prefix matcher wrongly matches",
            left: "cuda:sm89",
            right: "cuda:sm8",
            expect_match: false,
        },
        MatchVector {
            name: "prefix_left_shorter",
            clause: "KISS-CLASSIFY-6.8-0002",
            axis: "prefix",
            note: "left is a proper prefix of right -- the same defect in the other direction, which a one-sided starts_with test misses",
            left: "cuda:sm89",
            right: "cuda:sm890",
            expect_match: false,
        },
        MatchVector {
            name: "feature_implication",
            clause: "KISS-CLASSIFY-6.8-0002",
            axis: "feature-implication",
            note: "ordinal near-miss: a matcher treating a later architecture as satisfying an earlier one (sm90 implies sm89) wrongly matches. cuda.md is explicit that these are different cells, not a range",
            left: "cuda:sm89",
            right: "cuda:sm90",
            expect_match: false,
        },
        MatchVector {
            name: "case_fold",
            clause: "KISS-CLASSIFY-6.8-0002",
            axis: "case",
            note: "capability-side case difference: matching is case-SENSITIVE (KISS-CLASSIFY-6.8-0005 ties the charset rule to this clause). The namespace is held equal so the row isolates the case axis and does not also change the namespace",
            left: "cuda:sm89",
            right: "cuda:SM89",
            expect_match: false,
        },
        MatchVector {
            name: "equal_control_vulkan",
            clause: "KISS-CLASSIFY-6.8-0002",
            axis: "control",
            note: "the vulkan-side control -- present so a consumer excluding the cuda namespace is not left with only no-match rows",
            left: VK,
            right: VK,
            expect_match: true,
        },
        MatchVector {
            name: "member_ordering",
            clause: "KISS-CLASSIFY-6.8-0002",
            axis: "ordering",
            note: "same ops- MEMBERS {a,b,r}, different order (abr vs bar): a matcher that decodes the juxtaposed set and compares it as a SET wrongly matches. The right side is non-canonical under vulkan V-3 and a byte-exact matcher must decline it WITHOUT knowing that",
            left: VK,
            right: "vulkan:sg64.ops-bar.arith-f16.cm-none.cv-none",
            expect_match: false,
        },
        MatchVector {
            name: "member_subset",
            clause: "KISS-CLASSIFY-6.8-0002",
            axis: "subset",
            note: "right's ops- members {a,b} are a proper SUBSET of left's {a,b,r}: a subset/capability-satisfaction matcher wrongly matches",
            left: VK,
            right: "vulkan:sg64.ops-ab.arith-f16.cm-none.cv-none",
            expect_match: false,
        },
    ]
}

/// One decline vector: a malformed (or wrong-schema, or reserved) input and the typed
/// [`KeyDecline`] the reference reader answers it with. The emitted artifact records
/// the codec's LIVE `from_token` result; `expected` is cross-checked against it in the
/// vectors test, so the published decline is both codec-emitted and spec-tied.
pub struct DeclineVector {
    pub name: &'static str,
    pub clause: &'static str,
    pub note: &'static str,
    pub token: String,
    pub expected: KeyDecline,
}

const A_GOLDEN: &str = "sk4|bin|f32|cuda:sm89|ix32|grid|r2|co/00/v4/d16/f;co/00/v4/d16/f;co/00/v4/d16/f|-";

/// The A.2 / recognition-surface decline vectors — the negative half of the byte-match
/// surface. Covers the closed-set membership declines (unknown vs reserved dtype and
/// op-family), the §6.7-0015 version signpost-vs-wall split, and the grown precision
/// fields' malformed forms.
pub fn decline_vectors() -> Vec<DeclineVector> {
    vec![
        DeclineVector {
            name: "unknown_dtype",
            clause: "KISS-CLASSIFY-6.1-0001",
            note: "dtype outside the closed 24-token set",
            token: A_GOLDEN.replacen("|f32|", "|f99|", 1),
            expected: KeyDecline::UnknownDtype,
        },
        DeclineVector {
            name: "reserved_dtype",
            clause: "KISS-CLASSIFY-6.1-0001",
            note: "reserved fnuz dtype: recognized on parse, distinct from unknown",
            token: A_GOLDEN.replacen("|f32|", "|f8e4m3fnuz|", 1),
            expected: KeyDecline::ReservedDtype,
        },
        DeclineVector {
            name: "unknown_op_family",
            clause: "KISS-CLASSIFY-6.5-0006",
            note: "op-family outside the closed 24-code set",
            token: A_GOLDEN.replacen("|bin|", "|zzz|", 1),
            expected: KeyDecline::UnknownOpFamily,
        },
        DeclineVector {
            name: "version_signpost_sk9",
            clause: "KISS-CLASSIFY-6.7-0015",
            note: "well-formed canonical OTHER version -> re-derive signpost, not a wall",
            token: A_GOLDEN.replacen("sk4", "sk9", 1),
            expected: KeyDecline::UnsupportedSchemaVersion { got: 9 },
        },
        DeclineVector {
            name: "version_signpost_sk3",
            clause: "KISS-CLASSIFY-6.7-0014",
            note: "this reference build ships no sk3 decoder arm: a persisted sk3 token is the signpost, never a silent cross-vocab decode",
            token: A_GOLDEN.replacen("sk4", "sk3", 1),
            expected: KeyDecline::UnsupportedSchemaVersion { got: 3 },
        },
        DeclineVector {
            name: "version_wall_leading_zero",
            clause: "KISS-CLASSIFY-6.7-0015",
            note: "non-canonical leading-zero sk04 is the malformed wall, not the signpost",
            token: A_GOLDEN.replacen("sk4|", "sk04|", 1),
            expected: KeyDecline::BadVersionPrefix,
        },
        DeclineVector {
            name: "redundant_acc_mp_all_default",
            clause: "KISS-CLASSIFY-6.7-0013",
            note: "the all-default (acc+mp) spelling is a forbidden redundant emission (rule d)",
            token: "sk4|red|f32|cuda:sm89|ix32|warp|r2|co/00/v1/d8/f;co/00/v1/da/f|rall|f32/st".to_string(),
            expected: KeyDecline::RedundantAccMpField,
        },
        DeclineVector {
            name: "acc_mp_bad_precision_code",
            clause: "KISS-CLASSIFY-6.7-0013",
            note: "the (acc+mp) field with an unrecognized math-precision code (zz)",
            token: "sk4|red|f32|cuda:sm89|ix32|warp|r2|co/00/v1/d8/f;co/00/v1/da/f|rall|f64/zz".to_string(),
            expected: KeyDecline::BadAccMpField,
        },
        DeclineVector {
            name: "contraction_reserved_weight_dtype",
            clause: "KISS-CLASSIFY-6.7-0009",
            note: "a reserved fnuz dtype inside the gem precision group declines as reserved",
            token: "sk4|gem|f32|cuda:sm89|ix32|grid|r2|co/00/v4/d16/f;co/00/v4/d16/f;co/00/v4/d16/f|-|ctll/d16/f32/f8e4m3fnuz/f32/st".to_string(),
            expected: KeyDecline::ReservedDtype,
        },
        DeclineVector {
            name: "contraction_bad_precision_code",
            clause: "KISS-CLASSIFY-6.7-0009",
            note: "the gem precision group with an unrecognized math-precision code (zz)",
            token: "sk4|gem|f32|cuda:sm89|ix32|grid|r2|co/00/v4/d16/f;co/00/v4/d16/f;co/00/v4/d16/f|-|ctll/d16/f32/f32/f32/zz".to_string(),
            expected: KeyDecline::BadContractionField,
        },
        // §6.6-0009 / §6.7-0005 (#160): a reduce `x<hh>` whose reduced set has a canonical
        // `-`/`rall`/`rlast` encoding for its rank overloads a sentinel — decline distinctly.
        DeclineVector {
            name: "noncanonical_reduce_all_axes_r2",
            clause: "KISS-CLASSIFY-6.7-0005",
            note: "x03 at rank 2 is the all-axes set — MUST be rall, never a bitmask",
            token: "sk4|red|f32|cuda:sm89|ix32|warp|r2|co/00/v1/d8/f;co/00/v1/da/f|x03".to_string(),
            expected: KeyDecline::NonCanonicalReduceField,
        },
        DeclineVector {
            name: "noncanonical_reduce_trailing_r2",
            clause: "KISS-CLASSIFY-6.7-0005",
            note: "x02 at rank 2 is the lone innermost axis — MUST be rlast, never a bitmask",
            token: "sk4|red|f32|cuda:sm89|ix32|warp|r2|co/00/v1/d8/f;co/00/v1/da/f|x02".to_string(),
            expected: KeyDecline::NonCanonicalReduceField,
        },
        DeclineVector {
            name: "noncanonical_reduce_rank1",
            clause: "KISS-CLASSIFY-6.7-0005",
            note: "x01 at rank 1 is both all-axes and lone-trailing (they coincide) — MUST be rall (§6.6-0009 tie-break)",
            token: "sk4|red|f32|cuda:sm89|ix32|warp|r1|co/00/v1/d8/f;co/00/v1/da/f|x01".to_string(),
            expected: KeyDecline::NonCanonicalReduceField,
        },
        DeclineVector {
            name: "noncanonical_reduce_empty",
            clause: "KISS-CLASSIFY-6.7-0005",
            note: "x00 is the empty reduced set — that is not a reduction, spelled `-`, never a bitmask",
            token: "sk4|red|f32|cuda:sm89|ix32|warp|r2|co/00/v1/d8/f;co/00/v1/da/f|x00".to_string(),
            expected: KeyDecline::NonCanonicalReduceField,
        },
        // §6.7-0009: a bit set for a non-existent axis (index >= rank) is a DIFFERENT producer
        // bug — kept visibly separate so a consumer can see both declines and tell them apart.
        DeclineVector {
            name: "out_of_range_reduce_mask_r2",
            clause: "KISS-CLASSIFY-6.7-0009",
            note: "x04 at rank 2 sets bit 2, an axis that does not exist — out-of-range mask, not a sentinel overload",
            token: "sk4|red|f32|cuda:sm89|ix32|warp|r2|co/00/v1/d8/f;co/00/v1/da/f|x04".to_string(),
            expected: KeyDecline::BadReduceField,
        },
        // §6.6-0009: a rank-0 (scalar) cell has no axis to reduce, so it admits only `-`. The
        // `rall`/`rlast` sentinels are not `x<hh>` masks, so they bypass the mask validator and
        // are pinned by §6.6-0009's rank-0 sentence — and they SPLIT on its real-set-vs-cannot-
        // exist axis, NOT to one code: `rall` is the empty set spelled wrong (NonCanonical),
        // `rlast` names an axis the rank does not have (out-of-range → BadReduceField).
        DeclineVector {
            name: "noncanonical_reduce_rall_rank0",
            clause: "KISS-CLASSIFY-6.6-0009",
            note: "rall at rank 0 is the full set of zero axes = the empty set — a real set spelled wrong that `-` owns, exactly x00's shape",
            token: "sk4|red|f32|cuda:sm89|ix32|warp|r0|co/00/v1/d8/f;co/00/v1/da/f|rall".to_string(),
            expected: KeyDecline::NonCanonicalReduceField,
        },
        DeclineVector {
            name: "out_of_range_reduce_rlast_rank0",
            clause: "KISS-CLASSIFY-6.6-0009",
            note: "rlast at rank 0 names a lone innermost axis that does not exist — a set that cannot exist for the rank, exactly x04@r2's out-of-range shape",
            token: "sk4|red|f32|cuda:sm89|ix32|warp|r0|co/00/v1/d8/f;co/00/v1/da/f|rlast".to_string(),
            expected: KeyDecline::BadReduceField,
        },
    ]
}

// ---- JSON emission (stdlib-only; the crate shares no code with an impl, §6.5) ---

/// Escape a string for a JSON double-quoted value. All authored strings here are
/// ASCII with no quote/backslash, but this is defensive so a note edit cannot emit
/// malformed JSON.
fn json_str(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// The STABLE published spelling of a [`KeyDecline`] for the artifact — the decline
/// contract, decoupled from Rust's `Debug` (documented as NOT a stable format, so
/// `format!("{e:?}")` would let a field rename or a struct-variant reshape silently
/// re-spell a value three implementations byte-compare against). Returns the decline
/// KIND and an optional structured numeric payload `(key, value)`, so a consumer
/// matches on the kind and reads the payload as a JSON number rather than parsing Rust
/// struct syntax (`"UnsupportedSchemaVersion { got: 3 }"`) out of a string.
///
/// WILDCARD-FREE and compiled on both CI legs (no `#[cfg]`): a new `KeyDecline` variant
/// is a generation-time build failure (E0004) here, not a new spelling that appears in
/// the artifact unannounced. Payload-free variants keep their pre-existing spellings, so
/// this is a hardening of the two payloaded variants, not a wire change for the rest.
fn decline_wire(e: &KeyDecline) -> (&'static str, Option<(&'static str, String)>) {
    match e {
        KeyDecline::WrongFieldCount { got } => ("WrongFieldCount", Some(("got", got.to_string()))),
        KeyDecline::BadVersionPrefix => ("BadVersionPrefix", None),
        KeyDecline::UnsupportedSchemaVersion { got } => ("UnsupportedSchemaVersion", Some(("got", got.to_string()))),
        KeyDecline::BadRank => ("BadRank", None),
        KeyDecline::BadWorkClass => ("BadWorkClass", None),
        KeyDecline::BadOperandSubKey => ("BadOperandSubKey", None),
        KeyDecline::BadReduceField => ("BadReduceField", None),
        KeyDecline::BadContractionField => ("BadContractionField", None),
        KeyDecline::UppercaseOrWidthHex => ("UppercaseOrWidthHex", None),
        KeyDecline::UnknownOpFamily => ("UnknownOpFamily", None),
        KeyDecline::UnknownDtype => ("UnknownDtype", None),
        KeyDecline::ReservedDtype => ("ReservedDtype", None),
        KeyDecline::TokenLengthOutOfBound { len } => ("TokenLengthOutOfBound", Some(("len", len.to_string()))),
        KeyDecline::TooManyOperands { got } => ("TooManyOperands", Some(("got", got.to_string()))),
        KeyDecline::BadTargetGrammar => ("BadTargetGrammar", None),
        KeyDecline::BadTargetCharset => ("BadTargetCharset", None),
        KeyDecline::ContractionPresenceMismatch => ("ContractionPresenceMismatch", None),
        KeyDecline::ReduceNotGatedToRed => ("ReduceNotGatedToRed", None),
        KeyDecline::BadAccMpField => ("BadAccMpField", None),
        KeyDecline::RedundantAccMpField => ("RedundantAccMpField", None),
        KeyDecline::NonCanonicalReduceField => ("NonCanonicalReduceField", None),
    }
}

/// The wire KIND of every `KeyDecline` variant, for the injectivity guard. Exhaustiveness
/// (the `decline_wire` match above, E0004-guarded) proves every variant maps to SOMETHING;
/// it does NOT prove two variants don't map to the SAME string — an injective failure is
/// silent (green build, two declines collapsed in the artifact). The vectors test asserts
/// these are pairwise distinct against a pinned count.
///
/// This vec is a hand-listed representative per variant. KEEP IN LOCKSTEP with
/// `decline_wire`: a new `KeyDecline` variant is an E0004 there, and the pinned count in
/// the injectivity test is the deliberate second gate so this list cannot silently fall
/// behind (KISS-Conform: asserted counts are pinned, not computed).
pub fn all_decline_wire_kinds() -> Vec<&'static str> {
    [
        KeyDecline::WrongFieldCount { got: 0 },
        KeyDecline::BadVersionPrefix,
        KeyDecline::UnsupportedSchemaVersion { got: 0 },
        KeyDecline::BadRank,
        KeyDecline::BadWorkClass,
        KeyDecline::BadOperandSubKey,
        KeyDecline::BadReduceField,
        KeyDecline::BadContractionField,
        KeyDecline::UppercaseOrWidthHex,
        KeyDecline::UnknownOpFamily,
        KeyDecline::UnknownDtype,
        KeyDecline::ReservedDtype,
        KeyDecline::TokenLengthOutOfBound { len: 0 },
        KeyDecline::TooManyOperands { got: 0 },
        KeyDecline::BadTargetGrammar,
        KeyDecline::BadTargetCharset,
        KeyDecline::ContractionPresenceMismatch,
        KeyDecline::ReduceNotGatedToRed,
        KeyDecline::BadAccMpField,
        KeyDecline::RedundantAccMpField,
        KeyDecline::NonCanonicalReduceField,
    ]
    .iter()
    .map(|e| decline_wire(e).0)
    .collect()
}

/// Emit the reference-vectors artifact as pretty JSON (2-space indent, trailing
/// newline) — the exact bytes committed to `conformance/corpus/structure_key_vectors.json`.
/// The vectors test asserts this output equals the committed file byte-for-byte
/// (`emit() == committed`), so a stale artifact fails CI.
///
/// Every token is produced HERE by the codec: positives via [`StructureKey::to_token`],
/// declines via [`from_token`]. A "decline" input that unexpectedly parses is a
/// generation-time panic, not a silently-wrong artifact.
pub fn emit_reference_vectors_json() -> String {
    let usable: Vec<&str> = DTYPES.iter().copied().filter(|d| !RESERVED_DTYPES.contains(d)).collect();

    let mut s = String::new();
    s.push_str("{\n");
    s.push_str(&format!("  \"schema\": {},\n", json_str(VECTORS_SCHEMA)));
    // **KNOWN DEFECT - #218, fix scheduled with the coordinated artifact cut.**
    // `generated_from` must name the GENERATOR that emitted these bytes - this
    // module - not the document that specifies them. Provenance names the producer;
    // agreement with an annex is a separate relation, and neither settles the other.
    // Changes published bytes, so it moves with `source_commit` above, not before it.
    s.push_str("  \"generated_from\": \"spec/classify.md\",\n");
    s.push_str(&format!("  \"source_commit\": {},\n", json_str(SOURCE_COMMIT)));
    s.push_str("  \"clause\": \"KISS-CLASSIFY-6.7\",\n");
    // Per-namespace vocabulary provenance (#200). Emitted for exactly the
    // namespaces the vectors actually embed, DERIVED from the vectors rather than
    // listed by hand — a hand-listed set can omit a namespace some vector uses,
    // which is the omission this block exists to make impossible.
    {
        let pv = positive_vectors();
        // GENERATION-TIME VALIDATION (#200 req 3): every embedded target must be
        // well-formed under its owning document's grammar, not merely stamped with a
        // version. A stamp catches a bump; it does not catch a token malformed when
        // written — and no consumer can catch that either, because they copy it.
        for v in &pv {
            validate_target_token(&v.key.target);
        }
        let mut seen: Vec<&str> = pv
            .iter()
            .map(|v| target_namespace(&v.key.target))
            .collect();
        seen.sort_unstable();
        seen.dedup();
        s.push_str("  \"namespace_vocabulary_note\": \"Each <namespace>: token is spelled in a vocabulary owned by that namespace's maintainer (KISS-CLASSIFY-6.8-0004), versioned independently of this artifact. These are the versions the tokens below were GENERATED AGAINST; a consumer asserting a vocabulary version (KISS-CLASSIFY-6.8-0009) asserts against these. The generator FAILS rather than emit a token whose vocabulary version it cannot state.\",\n");
        s.push_str("  \"namespace_vocabulary_versions\": {\n");
        for (i, ns) in seen.iter().enumerate() {
            let comma = if i + 1 < seen.len() { "," } else { "" };
            s.push_str(&format!("    {}: {}{}\n", json_str(ns), namespace_vocab_version(ns), comma));
        }
        s.push_str("  },\n");
    }
    s.push_str(&format!("  \"structure_key_schema_version\": {},\n", SCHEMA_VERSION));
    s.push_str("  \"token_prefix\": \"sk4\",\n");
    s.push_str("  \"dtype_axis_note\": \"recognition_set is all 24 tokens a reader MUST recognize on parse (reserved ones typed-decline, distinct from unknown); usable_set is the 22 a byte-match runs over. The two are different obligations (KISS-CLASSIFY-6.1-0001).\",\n");
    s.push_str(&format!("  \"recognition_count\": {},\n", DTYPES.len()));
    s.push_str(&format!("  \"usable_count\": {},\n", usable.len()));

    // dtype sets, in §6.1-table order (ordinal-significant per §6.19-0025).
    s.push_str("  \"dtype_recognition_set\": [\n");
    for (i, d) in DTYPES.iter().enumerate() {
        let comma = if i + 1 < DTYPES.len() { "," } else { "" };
        s.push_str(&format!("    {}{}\n", json_str(d), comma));
    }
    s.push_str("  ],\n");
    s.push_str("  \"dtype_usable_set\": [\n");
    for (i, d) in usable.iter().enumerate() {
        let comma = if i + 1 < usable.len() { "," } else { "" };
        s.push_str(&format!("    {}{}\n", json_str(d), comma));
    }
    s.push_str("  ],\n");
    s.push_str("  \"reserved_dtypes\": [\n");
    for (i, d) in RESERVED_DTYPES.iter().enumerate() {
        let comma = if i + 1 < RESERVED_DTYPES.len() { "," } else { "" };
        s.push_str(&format!("    {}{}\n", json_str(d), comma));
    }
    s.push_str("  ],\n");

    // target-namespace axis — the same machine-readable treatment the dtype axis got.
    // There is NO typed namespace enum at this schema version (StructureKey.target is the
    // §6.8-0001 free-form <namespace>:<capability-set> string), so `target_namespace` is
    // derived from `target`; the vectors test cross-checks it against the SERIALIZED token
    // with its own independent split, never against the same derivation, so the tag cannot
    // pass vacuously.
    let pos = positive_vectors();
    let mut namespaces: Vec<&str> = pos.iter().map(|v| target_namespace(&v.key.target)).collect();
    namespaces.sort_unstable();
    namespaces.dedup();
    s.push_str("  \"target_axis_note\": \"Each positive vector names the `target` capability token it requires and its `target_namespace`. A consumer implementing only some namespaces/architectures scopes the rest as capability EXCLUSIONS (conformant, KISS-CLASSIFY-6.8), never mismatches — on BOTH sub-axes: namespace (cuda vs vulkan) and capability/arch (sm89 vs sm90). With these tags a consumer reports N/N on the vectors it claims plus an explicit skip list, instead of N-1/N with a paragraph — the number stops depending on prose.\",\n");
    s.push_str("  \"target_namespaces\": [\n");
    for (i, ns) in namespaces.iter().enumerate() {
        let comma = if i + 1 < namespaces.len() { "," } else { "" };
        s.push_str(&format!("    {}{}\n", json_str(ns), comma));
    }
    s.push_str("  ],\n");
    // §6.8-0002 match axis. Each row is an ORDERED PAIR of capability tokens plus the
    // verdict a byte-exact matcher MUST return. The tokens are emitted HERE by the codec
    // from a fixed carrier key that differs ONLY in field 3, so a consumer gets both the
    // capability-level pair (to run its matcher on) and the structure_key-level pair (to
    // check its own verbatim carriage against).
    let mv = target_match_vectors();
    s.push_str("  \"target_match_note\": \"KISS-CLASSIFY-6.8-0002 pairs. `expect_match` is the verdict a BYTE-EXACT matcher must return for (`left`, `right`); `axis` names the forbidden logic the pair would fool. Matching is VOCABULARY-BLIND: the ordering/subset rows carry a right-hand side that is non-canonical under spec/namespaces/vulkan.md V-3, and a conformant matcher declines them WITHOUT consulting any namespace document -- needing to know it was non-canonical in order to decline it would itself violate this clause. `left_token`/`right_token` are the SAME carrier structure_key differing only in field 3, so a consumer can check verbatim carriage on the same rows. WHAT THIS SET DOES NOT ESTABLISH: passing it does not show a consumer DERIVES the capability suffix -- the suffix is a pass-through field (see coverage_note (e)); and the equal-pair CONTROLS are per-NAMESPACE on purpose, because target_axis_note lets a consumer exclude a whole namespace, which would otherwise strip the only control and leave a matcher that answers no-match for everything passing every remaining row.\",\n");
    s.push_str("  \"target_match_vectors\": [\n");
    for (i, m) in mv.iter().enumerate() {
        let comma = if i + 1 < mv.len() { "," } else { "" };
        // GENERATION-TIME GUARDS, both fail-closed:
        //  (1) arity/namespace -- the same gate the positives get, so a match row cannot
        //      publish a suffix malformed under the vocabulary that owns it (#200). It is
        //      deliberately silent on CANONICITY, which is what lets the ordering row exist.
        //  (2) round-trip -- the target must embed as ONE unambiguous field and survive
        //      parse byte-identically. This is the §6.8-0002 reduction itself (byte-exact
        //      token matching reduces to byte-exact target matching) enforced on the way
        //      out, and it is what a bespoke charset check would only approximate: a row
        //      carrying `|`, `;`, `/` or whitespace (§6.8-0005) cannot round-trip and is
        //      therefore unpublishable rather than silently mangled.
        let tok: Vec<String> = [m.left, m.right].into_iter().map(|tgt| {
            validate_target_token(tgt);
            let t = key("bin", "f32", tgt, WorkClass::Grid, 2, vec![co4(), co4(), co4()], Reduce::None, None).to_token();
            match from_token(&t) {
                Ok(k) if k.target == tgt => {}
                Ok(k) => panic!(
                    "match vector `{}`: target `{}` did not survive round-trip (got `{}`)",
                    m.name, tgt, k.target
                ),
                Err(e) => panic!(
                    "match vector `{}`: carrier token for target `{}` does not parse ({e:?}) -- the target is not embeddable as a single field (KISS-CLASSIFY-6.8-0005)",
                    m.name, tgt
                ),
            }
            t
        }).collect();
        // the verdict must BE byte-exactness, not a hand-set opinion of it: a row whose
        // expect_match disagrees with `left == right` is a wrong row, and publishing one
        // would teach consumers the opposite of the clause.
        assert_eq!(
            m.expect_match,
            m.left == m.right,
            "match vector `{}`: expect_match={} contradicts byte-exact equality of its own pair",
            m.name, m.expect_match
        );
        s.push_str("    {\n");
        s.push_str(&format!("      \"clause\": {},\n", json_str(m.clause)));
        s.push_str(&format!("      \"name\": {},\n", json_str(m.name)));
        s.push_str(&format!("      \"axis\": {},\n", json_str(m.axis)));
        s.push_str(&format!("      \"note\": {},\n", json_str(m.note)));
        s.push_str(&format!("      \"left\": {},\n", json_str(m.left)));
        s.push_str(&format!("      \"right\": {},\n", json_str(m.right)));
        s.push_str(&format!("      \"expect_match\": {},\n", m.expect_match));
        s.push_str(&format!("      \"left_token\": {},\n", json_str(&tok[0])));
        s.push_str(&format!("      \"right_token\": {}\n", json_str(&tok[1])));
        s.push_str(&format!("    }}{}\n", comma));
    }
    s.push_str("  ],\n");
    s.push_str("  \"mapping_guard_note\": \"The `decline` kind strings are KISS's vocabulary. KISS enforces their exhaustiveness at generation time (a new KeyDecline variant is a build error) — that protects only the KISS side. A consumer mapping these onto its own decline enum MUST guard the mapping itself; a variant added on either side silently staleness the table.\",\n");
    s.push_str("  \"coverage_note\": \"The positive vectors exercise the structure_key token GRAMMAR — field order, optional-field presence, sentinel spellings, work-class/dispatch, and decline verdicts — NOT the dtype vocabulary: they place only a few of the 22 usable dtypes in the dtype position, so a dtype-spelling divergence on a token that never appears is invisible to a byte-match against this set. Vocabulary agreement is a DIFFERENT instrument's job and IS closed there: the dtype-manifest gate — tools/test_kiss_dtypes_manifest.py, over conformance/corpus/dtype_manifest.json — asserts each dtype token's metadata, so a c128->c127 respell raises there, naming the token. Nor do the POSITIVE vectors test decline-side rules: rule (d) — rejecting the all-default redundant (acc+mp) form — is exercised only by the decline vector 'redundant_acc_mp_all_default' -> RedundantAccMpField (a deriver covers it by running the DECLINE vectors on the parse side, or by proving the redundant form unconstructible on the emit side; never by the positive byte-match). So 'the byte-match passed' means the token grammar agrees; the vocabulary is confirmed by the manifest and the decline-side rules by the decline vectors, not by this positive set. Three further blind spots, each with a DIFFERENT remedy so a reader knows what to do next: (c) the positives are a SAMPLE, not a census — a divergence that surfaces as a DIFFERENT cell (a shape this set never places) rather than a different spelling of the SAME cell is invisible, and is closed by sampling more cells, never by this set agreeing. (d) op-family ASSIGNMENT is upstream of the token — the op_family code is IN each token, but which concrete op maps to which §6.5-0006 family is the consumer's CLASSIFICATION, made before any token exists, so a party that files an op under the wrong family emits a token for a different cell (absent here), not a mismatched spelling of this one; a category error no token-level check can see, closed only by a classification instrument. [(c) and (d) share a shape — the byte-match tests spelling agreement on the cells sampled, not which cells EXIST or how ops MAP — but NOT a remedy, so they are named separately: (c) is a coverage gap, (d) is a category gap.] (e) Agreement on a PASS-THROUGH field is not evidence of independent DERIVATION of it. (Whether umbrella §5.3's implementation count should instead be per-FIELD is #208's OPEN question, owned there; this note claims only what THIS positive set cannot see.) A field a consumer carries VERBATIM (copied from a shared source, not derived from its own graph) byte-matches across every party sharing that source whether or not any DERIVED it and whether or not it is CORRECT. The lone pass-through field here is the `target` capability token's namespace-owned capability-SET SUFFIX — the part AFTER the colon (the namespace PREFIX `cuda`/`vulkan` is ThinkersJournal-registry-owned under §6.8 and IS checked; only the suffix is the maintainer's vocabulary). It is carried OPAQUELY by every consumer that compares it, and NONE derives it; one such `vulkan:` suffix once byte-matched green while it was MALFORMED against vulkan v4 — that incident is the proof this positive set cannot see the field. TWO DIFFERENT #200 instruments cover it, and they are not one: (i) the `namespace_vocabulary_versions` STAMP records which vocabulary version each embedded suffix was generated against — it proves BINDING, not CURRENCY: a stamp cannot report whether that vocabulary has SINCE moved, only which one was used, so detecting a STALE suffix needs a party comparing the stamp against the live namespace document (the §6.8-0008 manifest is that comparator, the sibling of the dtype-manifest gate above). The stamp alone is genuinely WEAKER than the arity gate; and (ii) the generation-time ARITY GATE refuses to emit a suffix whose FIELD COUNT violates the recorded arity, making a WRONG-ARITY suffix UNPUBLISHABLE — the instrument that closed the vulkan incident, which was an arity break. It counts `.`-separated fields only; it does NOT validate field CONTENT against the vocabulary, so a suffix with the right field count but a wrong field value (an unknown `ops-…` code, say) passes the gate and is caught by the namespace-vocabulary manifest (§6.8-0008), not here. The arity gate is also a TWO-LINK guarantee, not one: the generator cannot emit a token that violates the IN-CODE arity, and the in-code arity cannot drift from `spec/namespaces/<ns>.md` WHILE ITS BINDING TEST RUNS (arity is pinned in code and bound to the document by test — deliberately, to keep the emitter pure and the artifact path-independent). None of this is confirmed by this positive byte-match.\",\n");

    // positive vectors: token emitted by the codec (to_token).
    s.push_str("  \"positive_vectors\": [\n");
    for (i, v) in pos.iter().enumerate() {
        let comma = if i + 1 < pos.len() { "," } else { "" };
        s.push_str("    {\n");
        s.push_str(&format!("      \"clause\": {},\n", json_str(v.clause)));
        s.push_str(&format!("      \"name\": {},\n", json_str(v.name)));
        s.push_str(&format!("      \"note\": {},\n", json_str(v.note)));
        s.push_str(&format!("      \"target\": {},\n", json_str(&v.key.target)));
        s.push_str(&format!("      \"target_namespace\": {},\n", json_str(target_namespace(&v.key.target))));
        s.push_str(&format!("      \"token\": {}\n", json_str(&v.key.to_token())));
        s.push_str(&format!("    }}{}\n", comma));
    }
    s.push_str("  ],\n");

    // decline vectors: decline emitted by the codec (from_token, live).
    let dec = decline_vectors();
    s.push_str("  \"decline_vectors\": [\n");
    for (i, d) in dec.iter().enumerate() {
        let comma = if i + 1 < dec.len() { "," } else { "" };
        // the decline is codec-emitted (from_token, live) but PUBLISHED through the
        // stable wildcard-free mapping, never through Debug.
        let e = match from_token(&d.token) {
            Err(e) => e,
            Ok(_) => panic!(
                "decline vector `{}` unexpectedly parsed as a valid token: {}",
                d.name, d.token
            ),
        };
        let (kind, payload) = decline_wire(&e);
        s.push_str("    {\n");
        s.push_str(&format!("      \"clause\": {},\n", json_str(d.clause)));
        s.push_str(&format!("      \"name\": {},\n", json_str(d.name)));
        s.push_str(&format!("      \"note\": {},\n", json_str(d.note)));
        s.push_str(&format!("      \"token\": {},\n", json_str(&d.token)));
        match payload {
            // structured payload: a JSON number, not Rust struct syntax in a string.
            Some((k, v)) => {
                s.push_str(&format!("      \"decline\": {},\n", json_str(kind)));
                s.push_str(&format!("      {}: {}\n", json_str(k), v));
            }
            None => s.push_str(&format!("      \"decline\": {}\n", json_str(kind))),
        }
        s.push_str(&format!("    }}{}\n", comma));
    }
    s.push_str("  ]\n");
    s.push_str("}\n");
    s
}
